      f = t * g.fraction;
    } else if (this.moveMode === 'return') {
      f = t * t * (3 - 2 * t); // ease back
    } else {
      f = t; // committed move: constant speed, tile-to-tile
    }

    return {
      x: g.fromX + (g.toX - g.fromX) * f,
      z: g.fromZ + (g.toZ - g.fromZ) * f,
