    const now = this._gameTime(nowMs);
    this.moveMode = 'pre';
    this.glide = {
      fromX: this.visX,
      fromZ: this.visZ,
      toX,
      toZ,
      start: now,
      end: now + remaining / 1000,
      fraction: frac,
    };
    this._faceTowards(toX - this.visX, toZ - this.visZ);
